CREATE TABLE public.interview_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),job_role_id uuid NOT NULL REFERENCES public.job_roles(id),analysis_version_id uuid NOT NULL UNIQUE REFERENCES public.role_analysis_versions(id),purposes text[] NOT NULL DEFAULT '{}',role_state text NOT NULL DEFAULT 'existing' CHECK(role_state IN ('new','changing','existing')),incumbents integer NOT NULL DEFAULT 1 CHECK(incumbents>=1),locations text NOT NULL DEFAULT '',source_types text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','in_review','approved','rejected')),approved_by uuid,approved_at timestamptz,custom_output text NOT NULL DEFAULT '',is_fictional boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.interview_sessions TO authenticated; GRANT ALL ON public.interview_sessions TO service_role; REVOKE ALL ON public.interview_sessions FROM anon,PUBLIC; ALTER TABLE public.interview_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY interview_read ON public.interview_sessions FOR SELECT TO authenticated USING(true); CREATE POLICY interview_insert ON public.interview_sessions FOR INSERT TO authenticated WITH CHECK(public.can_edit_workspace()); CREATE POLICY interview_update ON public.interview_sessions FOR UPDATE TO authenticated USING(public.can_edit_workspace() OR public.has_role(auth.uid(),'hr_reviewer'));
CREATE TABLE public.interview_sources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.interview_sessions(id),name text NOT NULL CHECK(length(btrim(name))>0),source_type text NOT NULL CHECK(source_type IN ('incumbent','supervisor','hr','document','observation')),user_id uuid,UNIQUE(session_id,name,source_type));
GRANT SELECT,INSERT ON public.interview_sources TO authenticated; GRANT ALL ON public.interview_sources TO service_role; REVOKE ALL ON public.interview_sources FROM anon,PUBLIC; ALTER TABLE public.interview_sources ENABLE ROW LEVEL SECURITY;
CREATE POLICY sources_read ON public.interview_sources FOR SELECT TO authenticated USING(true); CREATE POLICY sources_insert ON public.interview_sources FOR INSERT TO authenticated WITH CHECK(public.can_edit_workspace());
CREATE TABLE public.interview_answers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.interview_sessions(id),source_id uuid NOT NULL REFERENCES public.interview_sources(id),module text NOT NULL CHECK(module IN ('A','B','C','D','E','F','G','H','I','S')),values jsonb NOT NULL,evidence_id uuid NOT NULL REFERENCES public.evidence_items(id),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.interview_answers TO authenticated; GRANT ALL ON public.interview_answers TO service_role; REVOKE ALL ON public.interview_answers FROM anon,PUBLIC; ALTER TABLE public.interview_answers ENABLE ROW LEVEL SECURITY;
CREATE POLICY answers_read ON public.interview_answers FOR SELECT TO authenticated USING(true); CREATE POLICY answers_insert ON public.interview_answers FOR INSERT TO authenticated WITH CHECK(public.can_edit_workspace() OR EXISTS(SELECT 1 FROM public.interview_sources s WHERE s.id=source_id AND s.user_id=auth.uid()) AND public.has_role(auth.uid(),'contributor'));
CREATE TABLE public.interview_outputs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),session_id uuid NOT NULL REFERENCES public.interview_sessions(id),output_type text NOT NULL,content text NOT NULL,evidence_ids uuid[] NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status='draft'),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.interview_outputs TO authenticated; GRANT ALL ON public.interview_outputs TO service_role; REVOKE ALL ON public.interview_outputs FROM anon,PUBLIC; ALTER TABLE public.interview_outputs ENABLE ROW LEVEL SECURITY;
CREATE POLICY outputs_read ON public.interview_outputs FOR SELECT TO authenticated USING(true); CREATE POLICY outputs_insert ON public.interview_outputs FOR INSERT TO authenticated WITH CHECK(public.can_edit_workspace());
CREATE INDEX ON public.interview_answers(session_id); CREATE INDEX ON public.interview_sources(session_id);
CREATE FUNCTION public.interview_required(p text[]) RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT coalesce(array_agg(DISTINCT m ORDER BY m),'{}') FROM unnest(p) purpose CROSS JOIN LATERAL unnest(CASE purpose WHEN 'selection' THEN ARRAY['A','B','C','D','F','G'] WHEN 'training' THEN ARRAY['A','B','C','D','E','H'] WHEN 'performance' THEN ARRAY['A','B','C','H'] WHEN 'compensation' THEN ARRAY['A','B','D','F','G','S'] WHEN 'legal' THEN ARRAY['A','B','G'] ELSE ARRAY['A','B','D'] END) m $$;
CREATE FUNCTION public.interview_core_complete(m text,v jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=public AS $$ DECLARE cnt integer; i integer; BEGIN cnt:=CASE m WHEN 'A' THEN 5 WHEN 'B' THEN 6 WHEN 'C' THEN 6 WHEN 'D' THEN 3 WHEN 'E' THEN 3 WHEN 'F' THEN 3 WHEN 'G' THEN 4 WHEN 'H' THEN 3 WHEN 'I' THEN 3 WHEN 'S' THEN 3 ELSE 0 END; IF cnt=0 OR jsonb_typeof(v)<>'object' THEN RETURN false; END IF; FOR i IN 0..cnt-1 LOOP IF jsonb_typeof(v->i::text) IS DISTINCT FROM 'string' OR length(btrim(coalesce(v->>i::text,'')))=0 THEN RETURN false; END IF; END LOOP; IF m='B' THEN IF (v->>'2')!~'^[1-5]$' OR (v->>'4')!~'^[0-9]+(\.[0-9]+)?$' THEN RETURN false; END IF; IF (v->>'4')::numeric NOT BETWEEN 0 AND 100 THEN RETURN false; END IF; END IF; RETURN true; END $$;
CREATE FUNCTION public.interview_covered(sid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT cardinality(s.purposes)>0 AND btrim(s.locations)<>'' AND cardinality(s.source_types)>0 AND NOT EXISTS(SELECT 1 FROM unnest(public.interview_required(s.purposes)) m WHERE (SELECT count(DISTINCT a.source_id) FROM public.interview_answers a WHERE a.session_id=s.id AND a.module=m AND public.interview_core_complete(a.module,a.values))<CASE WHEN s.incumbents=1 THEN 1 ELSE 2 END) FROM public.interview_sessions s WHERE s.id=sid $$;
CREATE FUNCTION public.interview_output_allowed(p text[],t text,custom text) RETURNS boolean LANGUAGE sql IMMUTABLE SET search_path=public AS $$ SELECT ('selection'=ANY(p) AND t IN ('Competency summary','Hiring materials')) OR ('training'=ANY(p) AND t IN ('Training-needs summary','Training plan')) OR ('performance'=ANY(p) AND t IN ('Performance standards','Evaluation criteria')) OR ('compensation'=ANY(p) AND t IN ('Role-scope summary','Job-evaluation summary')) OR ('legal'=ANY(p) AND t IN ('Essential-functions documentation','Work-demands summary')) OR ('workforce'=ANY(p) AND t IN ('Capability needs summary','Succession needs summary')) OR ('redesign'=ANY(p) AND t='Task redesign summary') OR ('other'=ANY(p) AND t='Confirmed custom deliverable' AND btrim(custom)<>'') $$;
CREATE FUNCTION public.guard_interview() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.interview_sessions; sid uuid; e uuid; BEGIN PERFORM pg_advisory_xact_lock(710112026); IF TG_TABLE_NAME='interview_sessions' THEN IF TG_OP='UPDATE' AND OLD.status='approved' THEN RAISE EXCEPTION 'Approved analysis is immutable; create a new version'; END IF; IF cardinality(NEW.purposes)=0 OR NOT NEW.purposes<@ARRAY['selection','training','performance','compensation','legal','workforce','redesign','other'] THEN RAISE EXCEPTION 'Select a valid analysis purpose'; END IF; IF (SELECT job_role_id FROM public.role_analysis_versions WHERE id=NEW.analysis_version_id) IS DISTINCT FROM NEW.job_role_id THEN RAISE EXCEPTION 'Analysis must belong to the same role'; END IF; IF TG_OP='INSERT' AND NEW.status<>'draft' THEN RAISE EXCEPTION 'New interviews begin as drafts'; END IF; IF TG_OP='UPDATE' AND NOT public.can_edit_workspace() AND auth.uid() IS NOT NULL AND ((to_jsonb(NEW)-ARRAY['status','approved_by','approved_at']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','approved_by','approved_at']) OR NEW.status NOT IN ('approved','rejected')) THEN RAISE EXCEPTION 'Reviewer may change only the decision'; END IF; IF NEW.status IN ('in_review','approved') THEN IF NOT coalesce(public.interview_covered(NEW.id),false) THEN RAISE EXCEPTION 'Required interview modules are not covered'; END IF; IF EXISTS(SELECT 1 FROM public.evidence_conflicts c WHERE c.job_role_id=NEW.job_role_id AND c.status='open') THEN RAISE EXCEPTION 'Resolve open evidence conflicts first'; END IF; END IF; IF NEW.status='approved' THEN IF NOT public.has_role(auth.uid(),'hr_reviewer') THEN RAISE EXCEPTION 'Only HR reviewers may approve'; END IF; IF OLD.status<>'in_review' THEN RAISE EXCEPTION 'Submit the analysis for HR review first'; END IF; NEW.approved_by:=auth.uid(); NEW.approved_at:=now(); ELSE NEW.approved_by:=NULL; NEW.approved_at:=NULL; END IF; RETURN NEW; END IF; sid:=NEW.session_id; SELECT * INTO s FROM public.interview_sessions WHERE id=sid FOR UPDATE; IF TG_TABLE_NAME='interview_outputs' THEN IF s.status<>'approved' OR NOT coalesce(public.interview_covered(sid),false) OR EXISTS(SELECT 1 FROM public.evidence_conflicts WHERE job_role_id=s.job_role_id AND status='open') THEN RAISE EXCEPTION 'Output drafting requires complete coverage and HR approval'; END IF; IF NOT public.interview_output_allowed(s.purposes,NEW.output_type,s.custom_output) THEN RAISE EXCEPTION 'Output does not match the analysis purpose'; END IF; IF cardinality(NEW.evidence_ids)=0 THEN RAISE EXCEPTION 'Output requires evidence'; END IF; FOREACH e IN ARRAY NEW.evidence_ids LOOP IF NOT EXISTS(SELECT 1 FROM public.interview_answers a WHERE a.session_id=sid AND a.evidence_id=e) THEN RAISE EXCEPTION 'Output citation must belong to this analysis'; END IF; END LOOP; RETURN NEW; END IF; IF s.status<>'draft' THEN RAISE EXCEPTION 'Interview is frozen during review and after approval'; END IF; IF TG_TABLE_NAME='interview_answers' THEN IF NOT EXISTS(SELECT 1 FROM public.interview_sources WHERE id=NEW.source_id AND session_id=sid) OR (SELECT job_role_id FROM public.evidence_items WHERE id=NEW.evidence_id) IS DISTINCT FROM s.job_role_id THEN RAISE EXCEPTION 'Source and evidence must belong to the same analysis role'; END IF; IF jsonb_typeof(NEW.values)<>'object' THEN RAISE EXCEPTION 'Answers must be structured'; END IF; IF NEW.module='B' AND ((NEW.values->>'2'<>'' AND (NEW.values->>'2')!~'^[1-5]$') OR (NEW.values->>'4'<>'' AND ((NEW.values->>'4')!~'^[0-9]+(\.[0-9]+)?$' OR (NEW.values->>'4')::numeric NOT BETWEEN 0 AND 100))) THEN RAISE EXCEPTION 'Task importance must be 1–5 and time must be 0–100'; END IF; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_interview() FROM PUBLIC,anon,authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['interview_sessions','interview_sources','interview_answers','interview_outputs'] LOOP EXECUTE format('CREATE TRIGGER interview_guard BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.guard_interview()',t); EXECUTE format('CREATE TRIGGER interview_audit AFTER INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.log_workspace_change()',t); END LOOP; END $$;
CREATE FUNCTION public.guard_interview_evidence() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM pg_advisory_xact_lock(710112026); IF EXISTS(SELECT 1 FROM public.interview_answers a WHERE a.evidence_id=OLD.id) THEN RAISE EXCEPTION 'Interview evidence is append-only'; END IF; RETURN OLD; END $$;
CREATE TRIGGER interview_evidence_freeze BEFORE UPDATE OR DELETE ON public.evidence_items FOR EACH ROW EXECUTE FUNCTION public.guard_interview_evidence();
CREATE FUNCTION public.guard_legacy_output() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid; BEGIN PERFORM pg_advisory_xact_lock(710112026); IF TG_TABLE_NAME='hiring_packages' THEN aid:=NEW.analysis_version_id; ELSE SELECT analysis_version_id INTO aid FROM public.hiring_packages WHERE id=NEW.package_id; END IF; IF NOT EXISTS(SELECT 1 FROM public.interview_sessions s WHERE s.analysis_version_id=aid AND s.status='approved' AND 'selection'=ANY(s.purposes) AND public.interview_covered(s.id)) THEN RAISE EXCEPTION 'Hiring drafting requires a covered HR-approved selection interview'; END IF; RETURN NEW; END $$;
CREATE TRIGGER interview_hiring_gate BEFORE INSERT OR UPDATE ON public.hiring_packages FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_output(); CREATE TRIGGER interview_material_gate BEFORE INSERT OR UPDATE ON public.package_materials FOR EACH ROW EXECUTE FUNCTION public.guard_legacy_output();
REVOKE ALL ON FUNCTION public.interview_required(text[]),public.interview_core_complete(text,jsonb),public.interview_covered(uuid),public.interview_output_allowed(text[],text,text),public.guard_interview_evidence(),public.guard_legacy_output() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.interview_required(text[]),public.interview_core_complete(text,jsonb),public.interview_covered(uuid),public.interview_output_allowed(text[],text,text) TO authenticated,service_role;